# Mundora RPG — Aurora dos Reinos (arquivo único Streamlit)
# pip install streamlit mercadopago
# streamlit run streamlit_app.py

from __future__ import annotations
import base64
import hashlib
import hmac
import os
import time
from pathlib import Path

import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(
    page_title="Aurora dos Reinos — Mundora RPG",
    page_icon="⚔️",
    layout="wide",
    initial_sidebar_state="expanded",
)

_GAME_B64 = """"""


def get_secret(name: str, default: str = "") -> str:
    try:
        if name in st.secrets:
            return str(st.secrets[name])
    except Exception:
        pass
    return os.environ.get(name, default)


MP_ACCESS_TOKEN = get_secret("MP_ACCESS_TOKEN", "")
REDEEM_SECRET = get_secret("MUNDORA_REDEEM_SECRET", "mundora-dev-secret-change-me")


def load_game_html() -> str:
    here = Path(__file__).resolve().parent
    for p in [here / "Mundora-RPG-completo.html", Path.cwd() / "Mundora-RPG-completo.html"]:
        try:
            if p.is_file() and p.stat().st_size > 1000:
                return p.read_text(encoding="utf-8", errors="replace")
        except Exception:
            pass
    return base64.b64decode(_GAME_B64.encode("ascii")).decode("utf-8", errors="replace")


def make_redeem_code(item_id: str) -> str:
    ts = str(int(time.time()) // 3600)
    raw = f"{item_id}|{ts}|{REDEEM_SECRET}"
    token = hmac.new(REDEEM_SECRET.encode(), raw.encode(), hashlib.sha256).hexdigest()[:8].upper()
    return f"MND-{item_id}-{token}"


def create_mp_preference(item_id, title, amount, method="pix"):
    if not MP_ACCESS_TOKEN:
        return {"error": "MP_ACCESS_TOKEN não configurado (Streamlit Secrets)."}
    try:
        import mercadopago
    except ImportError:
        return {"error": "Instale: pip install mercadopago"}
    sdk = mercadopago.SDK(MP_ACCESS_TOKEN)
    preference_data = {
        "items": [{
            "id": item_id,
            "title": str(title)[:120],
            "quantity": 1,
            "currency_id": "BRL",
            "unit_price": float(round(amount, 2)),
        }],
        "statement_descriptor": "MUNDORA RPG",
        "external_reference": item_id,
        "metadata": {"item_id": item_id, "method_hint": method},
        "payment_methods": {"installments": 12, "default_installments": 1},
    }
    if method == "pix":
        preference_data["payment_methods"]["default_payment_method_id"] = "pix"
    try:
        result = sdk.preference().create(preference_data)
        if result.get("status") not in (200, 201):
            return {"error": str(result)}
        pref = result.get("response") or {}
        return {
            "id": pref.get("id"),
            "init_point": pref.get("init_point") or pref.get("sandbox_init_point"),
            "sandbox_init_point": pref.get("sandbox_init_point"),
        }
    except Exception as e:
        return {"error": str(e)}


def main():
    st.sidebar.title("⚔️ Aurora dos Reinos")
    st.sidebar.caption("Mundora RPG · arquivo único")
    st.sidebar.markdown("---")
    st.sidebar.subheader("Pagamentos (opcional)")
    item_id = st.sidebar.text_input("ID do item premium", value="skin_dragon")
    title = st.sidebar.text_input("Título", value="Skin Dragão Mundora")
    amount = st.sidebar.number_input("Valor (R$)", min_value=9.90, value=9.90, step=0.10)
    method = st.sidebar.selectbox("Método", ["pix", "card"])
    if st.sidebar.button("Gerar checkout Mercado Pago"):
        res = create_mp_preference(item_id, title, amount, method)
        if res.get("error"):
            st.sidebar.error(res["error"])
        else:
            st.sidebar.success("Preferência criada")
            link = res.get("init_point") or res.get("sandbox_init_point")
            if link:
                st.sidebar.markdown(f"[Abrir pagamento]({link})")
            code = make_redeem_code(item_id)
            st.sidebar.code(code, language=None)
            st.sidebar.caption("Resgate o código no jogo (aba Pagamentos).")

    if st.sidebar.button("Gerar código de resgate (dev)"):
        st.sidebar.code(make_redeem_code(item_id), language=None)

    st.sidebar.markdown("---")
    st.sidebar.info("Visual Aurora · gameplay 100% grátis.")

    components.html(load_game_html(), height=920, scrolling=True)


if __name__ == "__main__":
    main()
